act_p as (select tablename || ' | ' || cmd || ' | ' || policyname as name, md5(coalesce(roles::text,'') || coalesce(qual,'') || coalesce(with_check,'')) as chk from pg_policies where schemaname = 'public')
select 'function missing' as drift, name from exp_f where name not in (select name from act_f)
union all select 'function extra', name from act_f where name not in (select name from exp_f)
union all select 'trigger missing', name from exp_t where name not in (select name from act_t)
union all select 'trigger extra', name from act_t where name not in (select name from exp_t)
union all select 'policy missing', name from exp_p where name not in (select name from act_p)
union all select 'policy extra', name from act_p where name not in (select name from exp_p)
union all select 'policy differs', e.name from exp_p e join act_p a on a.name = e.name where a.chk <> e.chk
order by 1, 2;
